const p = $input.first().json.body || {};
if (p.secret !== 'sv-mail-2026-09-17-Kq7') { throw new Error('bad secret'); }
const addrs = v => (String(v || '').match(/[A-Za-z0-9._%+'-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+/g) || []).map(x => x.toLowerCase());
const to = addrs(p.to), cc = addrs(p.cc);
if (!to.length) { throw new Error('no recipient'); }
// internal only: every recipient must be a sidanaventures.com address
const outside = to.concat(cc).filter(a => !/@sidanaventures\.com$/.test(a));
if (outside.length) { throw new Error('refused: external recipient(s) ' + outside.join(', ')); }
if (!p.subject || !p.html) { throw new Error('missing subject / html'); }
const b64 = Buffer.from(p.html, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n');
const mime = ['From: Aditya SV <investors@sidanaventures.com>', 'To: ' + to.join(', '), (cc.length ? 'Cc: ' + cc.join(', ') : 'X-Sidana: internal'), 'Subject: =?UTF-8?B?' + Buffer.from(p.subject, 'utf8').toString('base64') + '?=', 'MIME-Version: 1.0', 'Content-Type: text/html; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', b64].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
if (p.dry !== false) { throw new Error('DRY OK | to=' + to.join(', ') + ' | cc=' + cc.join(', ') + ' | subject=' + p.subject + ' | html chars=' + p.html.length); }
return [{ json: { to: to.join(', '), cc: cc.join(', '), subject: p.subject, raw } }];
